using Erp.Abstractions.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Microsoft.AspNetCore.Mvc;
namespace Erp.Modules.Purchasing;

internal static class PurchasingEndpoints
{
    public static void MapPurchasingEndpoints(this IEndpointRouteBuilder e)
    {
        var g = e.MapGroup("/api/v1/purchasing/orders").WithTags("Purchase Orders"); g.MapGet("/", (string? search, PurchaseOrderState? state, bool includeArchived, string? sort, bool descending, int page, int pageSize, [FromServices] IPurchaseOrderService s, CancellationToken t) => Run(() => s.SearchAsync(new(search, state, includeArchived, sort ?? "updated", descending, page < 1 ? 1 : page, pageSize < 1 ? 25 : pageSize), t))).RequirePermission(PurchasingPermissions.Read); g.MapGet("/{id:guid}", async (Guid id, [FromServices] IPurchaseOrderService s, CancellationToken t) => await s.GetAsync(id, t) is { } x ? Results.Ok(x) : Results.NotFound()).RequirePermission(PurchasingPermissions.Read); g.MapPost("/", (PurchaseOrderRequest r, [FromServices] IPurchaseOrderService s, CancellationToken t) => Run(() => s.CreateAsync(r, t), true)).RequirePermission(PurchasingPermissions.Manage); g.MapPut("/{id:guid}", (Guid id, PurchaseOrderRequest r, [FromServices] IPurchaseOrderService s, CancellationToken t) => Run(() => s.UpdateAsync(id, r, t))).RequirePermission(PurchasingPermissions.Manage); g.MapPost("/{id:guid}/send", (Guid id, PurchaseOrderTransitionRequest r, [FromServices] IPurchaseOrderService s, CancellationToken t) => Run(() => s.TransitionAsync(id, PurchaseOrderState.Sent, r.ConcurrencyStamp, t))).RequirePermission(PurchasingPermissions.Approve); g.MapPost("/{id:guid}/confirm", (Guid id, PurchaseOrderTransitionRequest r, [FromServices] IPurchaseOrderService s, CancellationToken t) => Run(() => s.TransitionAsync(id, PurchaseOrderState.Confirmed, r.ConcurrencyStamp, t))).RequirePermission(PurchasingPermissions.Approve); g.MapPost("/{id:guid}/cancel", (Guid id, PurchaseOrderTransitionRequest r, [FromServices] IPurchaseOrderService s, CancellationToken t) => Run(() => s.TransitionAsync(id, PurchaseOrderState.Cancelled, r.ConcurrencyStamp, t))).RequirePermission(PurchasingPermissions.Cancel); g.MapPost("/{id:guid}/archive", (Guid id, PurchaseOrderTransitionRequest r, [FromServices] IPurchaseOrderService s, CancellationToken t) => Run(() => s.SetArchivedAsync(id, r.ConcurrencyStamp, true, t))).RequirePermission(PurchasingPermissions.Archive); g.MapPost("/{id:guid}/reactivate", (Guid id, PurchaseOrderTransitionRequest r, [FromServices] IPurchaseOrderService s, CancellationToken t) => Run(() => s.SetArchivedAsync(id, r.ConcurrencyStamp, false, t))).RequirePermission(PurchasingPermissions.Archive);
        var sourcing = e.MapGroup("/api/v1/purchasing/suppliers").WithTags("Supplier sourcing");
        sourcing.MapGet("/contracts", ([FromServices] ISupplierSourcingService s, CancellationToken t) => Run(() => s.ContractsAsync(t))).WithSummary("List supplier contracts").RequirePermission(PurchasingPermissions.SupplierContractRead);
        sourcing.MapGet("/contracts/{id:guid}", async (Guid id, [FromServices] ISupplierSourcingService s, CancellationToken t) => await s.ContractAsync(id, t) is { } contract ? Results.Ok(contract) : Results.NotFound()).WithSummary("Get a supplier contract").RequirePermission(PurchasingPermissions.SupplierContractRead);
        sourcing.MapPost("/contracts", (SupplierContractRequest r, [FromServices] ISupplierSourcingService s, CancellationToken t) => Run(() => s.CreateContractAsync(r, t), true)).WithSummary("Create a draft supplier contract").RequirePermission(PurchasingPermissions.SupplierContractManage);
        sourcing.MapPost("/contracts/{id:guid}/activate", (Guid id, SupplierContractActionRequest r, [FromServices] ISupplierSourcingService s, CancellationToken t) => Run(() => s.TransitionContractAsync(id, SupplierContractState.Active, r, t))).WithSummary("Activate a supplier contract").RequirePermission(PurchasingPermissions.SupplierContractManage);
        sourcing.MapPost("/contracts/{id:guid}/terminate", (Guid id, SupplierContractActionRequest r, [FromServices] ISupplierSourcingService s, CancellationToken t) => Run(() => s.TransitionContractAsync(id, SupplierContractState.Terminated, r, t))).WithSummary("Terminate an active supplier contract").RequirePermission(PurchasingPermissions.SupplierContractManage);
        sourcing.MapGet("/evaluations", (Guid? supplierId, [FromServices] ISupplierSourcingService s, CancellationToken t) => Run(() => s.EvaluationsAsync(supplierId, t))).WithSummary("List supplier performance evaluations").RequirePermission(PurchasingPermissions.SupplierEvaluationRead);
        sourcing.MapGet("/evaluations/{id:guid}", async (Guid id, [FromServices] ISupplierSourcingService s, CancellationToken t) => await s.EvaluationAsync(id, t) is { } evaluation ? Results.Ok(evaluation) : Results.NotFound()).WithSummary("Get a supplier performance evaluation").RequirePermission(PurchasingPermissions.SupplierEvaluationRead);
        sourcing.MapPost("/evaluations", (SupplierEvaluationRequest r, [FromServices] ISupplierSourcingService s, CancellationToken t) => Run(() => s.EvaluateSupplierAsync(r, t), true)).WithSummary("Record a supplier performance evaluation").RequirePermission(PurchasingPermissions.SupplierEvaluate);
    }
    private static async Task<IResult> Run<T>(Func<Task<T>> action, bool created = false) { try { var x = await action(); return created ? x switch { PurchaseOrderDto order => Results.Created($"/api/v1/purchasing/orders/{order.Id}", x), SupplierContractDto contract => Results.Created($"/api/v1/purchasing/suppliers/contracts/{contract.Id}", x), SupplierEvaluationDto evaluation => Results.Created($"/api/v1/purchasing/suppliers/evaluations/{evaluation.Id}", x), _ => Results.Ok(x) } : Results.Ok(x); } catch (PurchasingValidationException ex) { return Results.ValidationProblem(ex.Errors); } catch (PurchasingConcurrencyException ex) { return Results.Conflict(new { error = ex.Message }); } catch (KeyNotFoundException) { return Results.NotFound(); } }
}
